SORTED=sorted(TERMS,key=len,reverse=True)
PATTERN=re.compile(r'(?<![A-Za-zÄÖÜäöüß])('+'|'.join(re.escape(k)for k in SORTED)+r')(?![A-Za-zÄÖÜäöüß])',re.I)
LOWER={k.lower():v for k,v in TERMS.items()}

def translate(text):
    # The manufacturer's UA data occasionally types Cyrillic lookalikes inside
    # Latin engineering codes. Correct only code tokens, never Ukrainian prose.
    confusables=str.maketrans('АВЕКМНОРСТХаеорсух','ABEKMHOPCTXaeopcyx')
    def code_token(m):
        token=m[0]
        return token.translate(confusables)if re.search('[A-Za-z]',token)and re.search('[АВЕКМНОРСТХаеорсух]',token)and not re.search('[БГҐДЄЖЗИІЇЙЛПУФЦЧШЩЬЮЯбвгґдєжзиіїйклмнптфцчшщььюя]',token)else token
    text=re.sub(r'[A-Za-zА-Яа-яІЇЄҐіїєґ0-9+_.-]+',code_token,text)
    text=re.sub(r'(AWADUKT\s+)(?:РР|HРР|НРР)\b',lambda m:m[1]+('HPP'if'H'in m[0]or'Н'in m[0]else'PP'),text)
    text=PATTERN.sub(lambda m:LOWER[m[0].lower()],text)
    text=re.sub(r'(?<![A-Za-z])l/min\b','л/хв',text)
    text=re.sub(r'(?<![A-Za-z])im(?![A-Za-z])','у',text)
    text=re.sub(r'(?<![A-Za-z])m\.(?=\s+\d)','з',text)
    text=re.sub(r'(?<![A-Za-z])f\.?\s+(?=[А-Яа-яІЇЄҐіїєґ])','для ',text)
    text=re.sub(r'(?<![A-Za-z])u\.?\s*(?=UP-|клапан|інструмент)','і ',text)
    text=re.sub(r'(?<![A-Za-z])stab\.(?=\d)','stabil ',text)
    text=re.sub(r'\s+f\.?\s*$','',text)
    text=text.replace('_bar','_бар')
    text=re.sub(r'(?<=[\d\"\'])\s*[xхXХ]\s*(?=\d)',' × ',text)
    text=re.sub(r'(?<=\d)\s*Ah\b',' А·год',text)
    text=re.sub(r'аккумулятор','акумулятор',text,flags=re.I)
    text=re.sub(r'(акумулятор)\s+\1',r'\1',text,flags=re.I)
    text=re.sub(r'(?<=\d)\s*m\b',' м',text)
    text=re.sub(r'(?<![A-Za-z])mm\b','мм',text)
    text=re.sub(r'\bbar\b','бар',text,flags=re.I)
    text=re.sub(r'(?<=\d)\s*V\b',' В',text)
    text=re.sub(r'(?<=\d)\s*W\b',' Вт',text)
    def circuits(m):
        n=int(m[1]);ending='контур'if n%10==1 and n%100!=11 else'контури'if n%10 in [2,3,4]and n%100 not in [12,13,14]else'контурів'
        return str(n)+' '+ending
    text=re.sub(r'(\d+)\s+контури\b',circuits,text)
    text=re.sub(r'(\d+)\s+смуги\b',lambda m:m[1]+' '+('смуга'if int(m[1])%10==1 and int(m[1])%100!=11 else'смуги'if int(m[1])%10 in [2,3,4]and int(m[1])%100 not in [12,13,14]else'смужок'),text)
    text=re.sub(r'\s+([,.;:])',r'\1',text)
    text=re.sub(r'\s+',' ',text).strip(' ,;-')
    return text

