def title(source,category,class_name=''):
    text=re.sub(r'\bREHAU\b','',source,flags=re.I).strip()
    text=translate(text)
    text=re.sub(r'(датчик води)\s+\1',r'\1',text,flags=re.I)
    text=re.sub(r'\s+(?:для|з|без)\s*$','',text,flags=re.I)
    if class_name=='Schaft für Kunststoffschacht':
        text=re.sub(r'\bколодязь\b','',text,flags=re.I)
        return 'Шахта колодязя REHAU '+re.sub(r'\s+',' ',text).strip(' ,')
    if class_name=='Kunststoff-Schachtboden'and not re.search(r'основа|лоток|днище|дно',text,re.I):
        text=re.sub(r'\bколодязь\b','',text,flags=re.I)
        return 'Основа колодязя REHAU '+re.sub(r'\s+',' ',text).strip(' ,')
    if class_name=='Rohrmatte'and re.search(r'\b[оo]?BKT\b',text,re.I):
        text=re.sub(r'\b([оo]?BKT)[- ]модуль',r'\1',text,flags=re.I)
        text=re.sub(r'без швидкорознімна(?: муфта)?\s*/глуха заглушка','без швидкорознімної муфти та заглушки',text,flags=re.I)
        return 'Модуль термоактивації бетону REHAU '+text
    if class_name in ['Kanaldeckel mit Rahmen','Deckel/Gitter für Fahr- und Fußgängerbereiche']and 'чавунна кришка'in text.lower():
        text=re.sub(r'чавунна кришка','',text,flags=re.I)
        text=re.sub(r'дренажний колодязь','для дренажного колодязя',text,flags=re.I)
        text=re.sub(r'\bколодязь\b','для колодязя',text,flags=re.I)
        text=text.replace('без вентиляція','без вентиляції')
        return 'Чавунна кришка REHAU '+re.sub(r'\s+',' ',text).strip(' ,')
    if category.endswith('-pipes')or category=='ventilation-ducts'or class_name in ['Kunststoffrohr glatt','Mehrschichtrohr glatt','Vorisoliertes Kunststoffrohr','Kunststoffrohr gerippt','Drainage-/Infiltrationsrohr','Schutzrohr für Kunststoff-Rohrsystem']:
        name='Труба'
        for candidate,pattern in TYPE_PATTERNS:
            if 'труба'in candidate.lower():
                m=re.search(pattern,text,re.I)
                if m:
                    name=candidate;text=(text[:m.start()]+' '+text[m.end():]);break
        return name+' REHAU '+re.sub(r'\s+',' ',text).strip(' ,')
    matches=[]
    for name,pattern in TYPE_PATTERNS:
        if name=='Колодязь'and re.search(r'вставка пісковловлювача|муфта колодязя',text,re.I):continue
        if 'труба' in name.lower() and not (category.endswith('-pipes') or category=='ventilation-ducts' or class_name in ['Kunststoffrohr glatt','Mehrschichtrohr glatt','Vorisoliertes Kunststoffrohr','Kunststoffrohr gerippt']):continue
        m=re.search(pattern,text,re.I)
        if m:
            matches.append((m.start(),-len(m[0]),name,m))
    if matches:
        _,_,name,m=min(matches,key=lambda item:(item[0],item[1]))
        text=(text[:m.start()]+' '+text[m.end():]).strip()
        text=re.sub(r'\s+',' ',text).strip(' ,')
        return name+' REHAU '+text
    defaults={'pipe-fittings':'Фітинг','external-sewer-fittings':'Каналізаційний фітинг','internal-sewer-fittings':'Каналізаційний фітинг','water-heating-pipes':'Труба','underfloor-heating':'Комплектуюча поверхневого опалення','distribution-manifolds':'Колекторний вузол','pipe-installation-tools':'Монтажний інструмент','pipe-installation-components':'Монтажна комплектуюча','district-heating-components':'Комплектуюча тепломережі','geothermal-systems':'Геотермальна комплектуюча','ventilation-components':'Комплектуюча вентиляції','stormwater-infiltration-components':'Комплектуюча дощової каналізації','inspection-chambers':'Комплектуюча колодязя','sewer-installation-components':'Монтажна комплектуюча каналізації','heating-sensors-modules':'Модуль автоматики','heating-fittings':'Фітинг опалення','zone-control':'Компонент зонального керування','leak-protection':'Захист від протікання','district-heating-pipes':'Теплоізольована труба','ventilation-ducts':'Вентиляційна труба'}
    if class_name in ['Kunststoffrohr glatt','Mehrschichtrohr glatt','Vorisoliertes Kunststoffrohr','Kunststoffrohr gerippt']:return 'Труба REHAU '+text
    return defaults.get(category,'Інженерна комплектуюча')+' REHAU '+text
